use corpse_core::{startup,storage,inventory,debug_floor as debug,progression};
use serde_json::json;
fn main(){for seed in ["heart-audit-000071".to_string(),"生成-é-🌱-37".into(),format!("{}-56","x".repeat(256)),"qa-mixed-33cdd108d7485523".into()]{let result=(||{let mut r=startup::new_run_shell_revision(&seed,"Unblessed",false,38.)?;startup::ensure_floors(&mut r,40)?;for f in &r.floors{let ids:std::collections::HashSet<_>=f.encounters.as_ref().into_iter().flatten().flat_map(|e|e.actor_ids.iter().map(|id|*id as u64)).collect();let actual:f64=r.actors_at(f.depth).iter().filter(|a|ids.contains(&(a.id as u64))&&!a.heartless.value_or(false)).map(|a|inventory::heart_for(a,0.).unwrap().exp.value_or(0.)).sum();if actual!=f.enemy_blessing_budget.value_or(0.){return Err(format!("heart budget mismatch floor{} actual{actual} expected{}",f.depth,f.enemy_blessing_budget.value_or(0.)))}if r.actors_at(f.depth).iter().filter(|a|corpse_core::dreamwalking::is_nightmare(a)).count()!=4{return Err(format!("nightmare count floor{}",f.depth))}}if r.actors_at(40.).iter().filter(|a|corpse_core::finale::is_boss(a)).count()!=1{return Err("missing finale".into())}if seed=="heart-audit-000071"{let mut d=debug::create_run_revision(&seed,"Avatar",27,38.)?;while !d.offers.is_empty(){let id=d.offers[0].clone();progression::choose_offer(&mut d,&id).map_err(|e|e.to_string())?;debug::advance(&mut d)?;}debug::enter(&mut d)?;storage::validate_current_revision(&d).map_err(|e|e.to_string())?;}Ok::<_,String>(())})();println!("{}",json!({"seed":seed,"result":result}));}}
